import pytest
from inventory import add_item, remove_item, total_value

def test_add_item():
    inv = {}
    add_item(inv, "apple", 5)
    assert inv == {"apple": 5}
    add_item(inv, "apple", 3)
    assert inv == {"apple": 8}
    add_item(inv, "banana", 2)
    assert inv == {"apple": 8, "banana": 2}
    try:
        add_item(inv, "apple", -1)
        assert False, "Should raise ValueError"
    except ValueError:
        pass

def test_remove_item():
    inv = {"apple": 8, "banana": 2}
    remove_item(inv, "apple", 3)
    assert inv == {"apple": 5, "banana": 2}

    # Key error on unknown item
    try:
        remove_item(inv, "orange", 1)
        assert False, "Should raise KeyError"
    except KeyError:
        pass

    # Value error on removing more than current
    try:
        remove_item(inv, "banana", 3)
        assert False, "Should raise ValueError"
    except ValueError:
        pass

    # Exactly 0 deletes key
    remove_item(inv, "banana", 2)
    assert inv == {"apple": 5}
    assert "banana" not in inv

def test_total_value():
    inv = {"apple": 5, "banana": 2, "orange": 3}
    prices = {"apple": 1.5, "banana": 0.5} # orange missing from prices
    val = total_value(inv, prices)
    assert val == 5 * 1.5 + 2 * 0.5 + 3 * 0.0
    assert isinstance(val, float)

if __name__ == "__main__":
    test_add_item()
    test_remove_item()
    test_total_value()
    print("All tests passed!")

